import{_ as i,a0 as l,w as o,s as a,ao as d,I as n,x as e,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"RHCSA 系列（五）: RHEL7 中的進程管理：開機，關機 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（五）: RHEL7 中的進程管理：開機，關機 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（五）: RHEL7 中的進程管理：開機，關機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（五）: RHEL7 中的進程管理：開機，關機 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 05--Process Management in RHEL 7--Boot Shutdown and Everything in Between","title":"RHCSA 系列（五）: RHEL7 中的進程管理：開機，關機","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 05--Process Management in RHEL 7--Boot Shutdown and Everything in Between.md","filePath":"[post].md"}'),m={name:"RHCSA Series/RHCSA Series--Part 05--Process Management in RHEL 7--Boot Shutdown and Everything in Between.md"};function u(S,t,w,g,T,c){const s=l("Link");return o(),a("div",null,[t[28]||(t[28]=d('<h1 id="rhcsa-系列-五-rhel7-中的進程管理-開機-關機" tabindex="-1">RHCSA 系列（五）: RHEL7 中的進程管理：開機，關機 <a class="header-anchor" href="#rhcsa-系列-五-rhel7-中的進程管理-開機-關機" aria-label="Permalink to “RHCSA 系列（五）: RHEL7 中的進程管理：開機，關機”">​</a></h1><p>我們將概括和簡要地複習從你按開機按鈕來打開你的 RHEL 7 服務器到呈現出命令列界面的登錄屏幕之間所發生的所有事情，以此來作為這篇文章的開始。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/RHEL-7-Boot-Process.png" alt="RHEL 7 開機過程"></p><p><em>Linux 開機過程</em></p><p><strong>請注意：</strong></p><ol><li>相同的基本原則也可以應用到其他的 Linux 發行版本中，但可能需要較小的更改，並且</li><li>下面的描述並不是旨在給出開機過程的一個詳盡的解釋，而只是介紹一些基礎的東西</li></ol><h3 id="linux-開機過程" tabindex="-1">Linux 開機過程 <a class="header-anchor" href="#linux-開機過程" aria-label="Permalink to “Linux 開機過程”">​</a></h3>',7)),n("ol",null,[t[6]||(t[6]=d('<li><p>初始化 POST（加電自檢）並執行硬件檢查；</p></li><li><p>當 POST 完成後，系統的控制權將移交給啓動管理器的第一階段（first stage），它存儲在一個硬盤的引導扇區（對於使用 BIOS 和 MBR 的舊式的系統而言）或存儲在一個專門的 (U)EFI 分區上。</p></li><li><p>啓動管理器的第一階段完成後，接着進入啓動管理器的第二階段（second stage），通常大多數使用的是 GRUB（GRand Unified Boot Loader 的簡稱），它駐留在 <code>/boot</code> 中，然後開始加載內核和駐留在 RAM 中的初始化文件系統（被稱為 initramfs，它包含執行必要操作所需要的程序和二進制文件，以此來最終掛載真實的根文件系統）。</p></li><li><p>接着展示了閃屏（splash）過後，呈現在我們眼前的是類似下圖的畫面，它允許我們選擇一個操作系統和內核來啓動：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/RHEL-7-Boot-Screen.png" alt="RHEL 7 開機屏幕"></p><p><em>啓動菜單屏幕</em></p></li>',4)),n("li",null,[t[3]||(t[3]=n("p",null,"內核會對接入到系統的硬件進行設置，當根文件系統被掛載後，接着便啓動 PID 為 1 的進程，這個進程將開始初始化其他的進程並最終呈現給我們一個登錄提示符界面。",-1)),n("p",null,[t[1]||(t[1]=e("注意：假如我們想在啓動後查看這些信息，我們可以使用 ",-1)),p(s,{href:"https://linux.cn/article-3587-1.html"},{default:r(()=>[...t[0]||(t[0]=[e("dmesg 命令",-1)])]),_:1}),t[2]||(t[2]=e("，並使用這個系列裏的上一篇文章中介紹過的工具（注：即 grep）來過濾它的輸出。",-1))]),t[4]||(t[4]=n("p",null,[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/03/Login-Screen-Process-PID.png",alt:"登錄屏幕和進程的 PID"})],-1)),t[5]||(t[5]=n("p",null,[n("em",null,"登錄屏幕和進程的 PID")],-1))])]),t[29]||(t[29]=d(`<p>在上面的例子中，我們使用了大家熟知的 <code>ps</code> 命令來顯示在系統啓動過程中的一系列當前進程的信息，它們的父進程（或者換句話説，就是那個開啓這些進程的進程）為 systemd（大多數現代的 Linux 發行版本已經切換到的系統和服務管理器）：</p><pre><code># ps -o ppid,pid,uname,comm --ppid=1
</code></pre><p>記住 <code>-o</code>（為 -format 的簡寫）選項允許你以一個自定義的格式來顯示 ps 的輸出，以此來滿足你的需求；這個自定義格式使用 <code>man ps</code> 裏 STANDARD FORMAT SPECIFIERS 一節中的特定關鍵詞。</p><p>另一個你想自定義 ps 的輸出而不是使用其默認輸出的情形是：當你需要找到引起 CPU 或內存消耗過多的那些進程，並按照下列方式來對它們進行排序時：</p><pre><code># ps aux --sort=+pcpu              # 以 %CPU 來排序(增序)
# ps aux --sort=-pcpu              # 以 %CPU 來排序(降序)
# ps aux --sort=+pmem              # 以 %MEM 來排序(增序)
# ps aux --sort=-pmem              # 以 %MEM 來排序(降序)
# ps aux --sort=+pcpu,-pmem        # 結合 %CPU (增序) 和 %MEM (降序)來排列
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/ps-command-output.png" alt="http://www.tecmint.com/wp-content/uploads/2015/03/ps-command-output.png"></p><p><em>自定義 ps 命令的輸出</em></p><h3 id="systemd-的一個介紹" tabindex="-1">systemd 的一個介紹 <a class="header-anchor" href="#systemd-的一個介紹" aria-label="Permalink to “systemd 的一個介紹”">​</a></h3><p>在 Linux 世界中，很少有能比在主流的 Linux 發行版本中採用 systemd 引起更多的爭論的決定。systemd 的倡導者根據以下事實來表明其主要的優勢：</p>`,9)),n("ol",null,[t[10]||(t[10]=n("li",null,[n("p",null,"在系統啓動期間，systemd 允許併發地啓動更多的進程（相比於先前的 SysVinit，SysVinit 似乎總是表現得更慢，因為它一個接一個地啓動進程，檢查一個進程是否依賴於另一個進程，然後等待守護進程啓動才可以啓動的更多的服務)，並且")],-1)),t[11]||(t[11]=n("li",null,[n("p",null,"在一個運行着的系統中，它用作一個動態的資源管理器。這樣在啓動期間，當一個服務被需要時，才啓動它（以此來避免消耗系統資源）而不是在沒有一個合理的原因的情況下啓動額外的服務。")],-1)),n("li",null,[t[9]||(t[9]=n("p",null,"向後兼容 sysvinit 的腳本。",-1)),n("p",null,[t[8]||(t[8]=e("另外請閲讀: ",-1)),p(s,{href:"http://www.tecmint.com/systemd-replaces-init-in-linux/"},{default:r(()=>[...t[7]||(t[7]=[e("'init' 和 'systemd' 背後的故事",-1)])]),_:1})])])]),t[30]||(t[30]=d(`<p>systemd 由 systemctl 工具控制，假如你瞭解 SysVinit，你將會對以下的內容感到熟悉：</p><ul><li>service 工具，在舊一點的系統中，它被用來管理 SysVinit 腳本，以及</li><li>chkconfig 工具，為系統服務升級和查詢運行級別信息</li><li>shutdown 你一定使用過幾次來重啓或關閉一個運行的系統。</li></ul><p>下面的表格展示了使用傳統的工具和 systemctl 之間的相似之處：</p><div class="table-wrap"><table><thead><tr><th>舊式工具</th><th>Systemctl 等價命令</th><th>描述</th></tr></thead><tbody><tr><td>service name start</td><td>systemctl start name</td><td>啓動 name （這裏 name 是一個服務）</td></tr><tr><td>service name stop</td><td>systemctl stop name</td><td>停止 name</td></tr><tr><td>service name condrestart</td><td>systemctl try-restart name</td><td>重啓 name （如果它已經運行了）</td></tr><tr><td>service name restart</td><td>systemctl restart name</td><td>重啓 name</td></tr><tr><td>service name reload</td><td>systemctl reload name</td><td>重載 name 的配置</td></tr><tr><td>service name status</td><td>systemctl status name</td><td>顯示 name 的當前狀態</td></tr><tr><td>service - status-all</td><td>systemctl</td><td>顯示當前所有服務的狀態</td></tr><tr><td>chkconfig name on</td><td>systemctl enable name</td><td>通過一個特定的單元文件，讓 name 可以在系統啓動時運行（這個文件是一個符號鏈接）。啓用或禁用一個啓動時的進程，實際上是增加或移除一個到 /etc/systemd/system 目錄中的符號鏈接。</td></tr><tr><td>chkconfig name off</td><td>systemctl disable name</td><td>通過一個特定的單元文件，讓 name 可以在系統啓動時禁止運行（這個文件是一個符號鏈接）。</td></tr><tr><td>chkconfig -list name</td><td>systemctl is-enabled name</td><td>確定 name （一個特定的服務）當前是否啓用。</td></tr><tr><td>chkconfig - list</td><td>systemctl - type=service</td><td>顯示所有的服務及其是否啓用或禁用。</td></tr><tr><td>shutdown -h now</td><td>systemctl poweroff</td><td>關機</td></tr><tr><td>shutdown -r now</td><td>systemctl reboot</td><td>重啓系統</td></tr></tbody></table></div><p>systemd 也引進了單元（unit）（它可能是一個服務，一個掛載點，一個設備或者一個網絡套接字）和目標（target）（它們定義了 systemd 如何去管理和同時開啓幾個相關的進程，可以認為它們與在基於 SysVinit 的系統中的運行級別等價，儘管事實上它們並不等價）的概念。</p><h3 id="總結歸納" tabindex="-1">總結歸納 <a class="header-anchor" href="#總結歸納" aria-label="Permalink to “總結歸納”">​</a></h3><p>其他與進程管理相關，但並不僅限於下面所列的功能的任務有：</p><p><strong>1. 在考慮到系統資源的使用上，調整一個進程的執行優先級：</strong></p><p>這是通過 <code>renice</code> 工具來完成的，它可以改變一個或多個正在運行着的進程的調度優先級。簡單來説，調度優先級是一個允許內核（當前只支持 &gt;= 2.6 的版本）根據某個給定進程被分配的執行優先級（即友善度（niceness），從 -20 到 19）來為其分配系統資源的功能。</p><p><code>renice</code> 的基本語法如下：</p><pre><code># renice [-n] priority [-gpu] identifier
</code></pre><p>在上面的通用命令中，第一個參數是將要使用的優先級數值，而另一個參數可以是進程 ID（這是默認的設定），進程組 ID，用户 ID 或者用户名。一個常規的用户（即除 root 以外的用户）只可以更改他或她所擁有的進程的調度優先級，並且只能增加友善度的層次（這意味着佔用更少的系統資源）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Process-Scheduling-Priority.png" alt="在 Linux 中調整進程的優先級"></p><p><em>進程調度優先級</em></p><p><strong>2. 按照需要殺死一個進程（或終止其正常執行）：</strong></p>`,15)),n("p",null,[t[13]||(t[13]=e("更精確地説，殺死一個進程指的是通過 ",-1)),p(s,{href:"https://linux.cn/article-2116-1.html"},{default:r(()=>[...t[12]||(t[12]=[e("kill 或 pkill",-1)])]),_:1}),t[14]||(t[14]=e(" 命令給該進程發送一個信號，讓它優雅地（SIGTERM=15）或立即（SIGKILL=9）結束它的執行。",-1))]),t[31]||(t[31]=d(`<p>這兩個工具的不同之處在於前一個被用來終止一個特定的進程或一個進程組，而後一個則允許你通過進程的名稱和其他屬性，執行相同的動作。</p><p>另外， pkill 與 pgrep 相捆綁，pgrep 提供將受符合的進程的 PID 給 pkill 來使用。例如，在運行下面的命令之前：</p><pre><code># pkill -u gacanepa
</code></pre><p>查看一眼由 gacanepa 所擁有的 PID 或許會帶來點幫助：</p><pre><code># pgrep -l -u gacanepa
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Find-PIDs-of-User.png" alt="找到用户擁有的 PID"></p><p><em>找到用户擁有的 PID</em></p><p>默認情況下，kill 和 pkiill 都發送 SIGTERM 信號給進程，如我們上面提到的那樣，這個信號可以被忽略（即該進程可能會終止其自身的執行，也可能不終止），所以當你因一個合理的理由要真正地停止一個運行着的進程，則你將需要在命令列中帶上特定的 SIGKILL 信號：</p><pre><code># kill -9 identifier               # 殺死一個進程或一個進程組
# kill -s SIGNAL identifier        # 同上
# pkill -s SIGNAL identifier       # 通過名稱或其他屬性來殺死一個進程
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這篇文章中，我們解釋了在 RHEL 7 系統中，有關開機啓動過程的基本知識，並分析了一些可用的工具來幫助你通過使用一般的程序和 systemd 特有的命令來管理進程。</p><p>請注意，這個列表並不旨在涵蓋有關這個話題的所有花哨的工具，請隨意使用下面的評論欄來添加你自已鍾愛的工具和命令。同時歡迎你的提問和其他的評論。</p><hr>`,13)),n("p",null,[t[16]||(t[16]=e("via: ",-1)),p(s,{href:"http://www.tecmint.com/rhcsa-exam-boot-process-and-process-management/"},{default:r(()=>[...t[15]||(t[15]=[e("http://www.tecmint.com/rhcsa-exam-boot-process-and-process-management/",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=e("作者：",-1)),p(s,{href:"http://www.tecmint.com/author/gacanepa/"},{default:r(()=>[...t[17]||(t[17]=[e("Gabriel Cánepa",-1)])]),_:1}),t[21]||(t[21]=e(" 譯者：",-1)),p(s,{href:"https://github.com/FSSlc"},{default:r(()=>[...t[18]||(t[18]=[e("FSSlc",-1)])]),_:1}),t[22]||(t[22]=e(" 校對：",-1)),p(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[19]||(t[19]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[25]||(t[25]=e("本文由 ",-1)),p(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[23]||(t[23]=[e("LCTT",-1)])]),_:1}),t[26]||(t[26]=e(" 原創翻譯，",-1)),p(s,{href:"https://linux.cn/"},{default:r(()=>[...t[24]||(t[24]=[e("Linux中國",-1)])]),_:1}),t[27]||(t[27]=e(" 榮譽推出",-1))])])}const C=i(m,[["render",u]]);export{R as __pageData,C as default};
